  /* ---- Footer. NOT a bare `footer`: ESPN builds every card's action strip out of a <footer>
     too (.Card__Footer, the prism hashed variant, .contentItem__footer), all natively
     transparent. ---- */
  .PageFooter, .PageFooter__Footer, .PageFooter__QuickLinks, #global-footer,
  .footer, .Footer { background-color: #0d1117 !important; border-color: #2d333b !important; }
  .PageFooter a, .PageFooter__QuickLinks a, .Footer a { color: #8ab4d8 !important; }
