  /* ---- Footer legal / OneTrust settings strip (default near-white) ---- */
  .PageFooter__Legal, .PageFooter__Legal__Copyright, .ot-sdk-show-settings,
  #onetrust-consent-sdk .ot-sdk-row, .legal { color: #8b949e !important; }
  /* ---- OneTrust / Disney consent SDK. Banner and preference centre are solid #fff panels;
     everything between them is transparent except the footer, which paints its own #fff.
     .onetrust-pc-dark-filter is the scrim, not a surface — forcing it opaque hides the panel
     behind it. ---- */
  #onetrust-banner-sdk, #onetrust-pc-sdk, #onetrust-pc-sdk .ot-pc-footer {
    background-color: #1c2128 !important; }
  #onetrust-policy-text, #onetrust-policy-text *, #ot-pc-desc, #ot-pc-desc *,
  #onetrust-pc-sdk .ot-acc-txt, #onetrust-pc-sdk .ot-accordion-layout button {
    color: #c4cdd6 !important; }
  #onetrust-pc-btn-handler {
    background-color: transparent !important; color: #e6edf3 !important;
    border-color: #8b949e !important; }
  /* Panel links keep OneTrust's tenant blue #0079bc (3.4:1 on dark). The token behind it
     (--ot-action-blue) also fills the Accept / Reject buttons, where it still passes, so
     repaint the links, not the token. OneTrust's rule is !important at (2,0,1), so the leading
     `body` wins the tie, and `[href]` is needed because their selector is `#onetrust-consent-
     sdk #onetrust-banner-sdk a[href]`. */
  body #onetrust-consent-sdk #onetrust-banner-sdk a[href],
  body #onetrust-consent-sdk #onetrust-banner-sdk .ot-link-btn,
  body #onetrust-consent-sdk #onetrust-pc-sdk a[href],
  body #onetrust-consent-sdk #onetrust-pc-sdk .ot-link-btn,
  body #onetrust-consent-sdk #onetrust-pc-sdk .ot-ven-link,
  body #onetrust-consent-sdk #onetrust-pc-sdk .privacy-notice-link {
    color: #5fb0e6 !important; }
  /* Both are black artwork on transparent. The wordmark is REPLACED content (`content:
     url(data:...)`) on the .ot-pc-logo box itself; its nested <img> is 0x0. */
  #onetrust-pc-sdk .ot-pc-logo, #onetrust-banner-sdk .banner_logo,
  #onetrust-pc-sdk .ot-close-icon { filter: invert(1) !important; }
  /* The accordion chevron is a data-URI SVG whose <path> declares no fill, so it paints black;
     its box is transparent, so inverting the box flips only the glyph. */
  #onetrust-pc-sdk .ot-plus-minus { filter: invert(1) !important; }
  /* A `border-top` on a ::before, which the blanket `*` reset cannot reach. */
  #onetrust-banner-sdk #onetrust-button-group-parent::before {
    border-top-color: #2d333b !important; }
  /* The "List of Partners" sub-view is a SECOND screen the panel-level rule never reaches: the
     Allow-All strip and each vendor accordion row paint their own near-white, and the funnel
     opens a pure-white popover, which floats and takes the raised tone. */
  #onetrust-pc-sdk #ot-sel-blk, #onetrust-pc-sdk .ot-acc-hdr {
    background-color: #21262d !important; }
  #onetrust-pc-sdk #ot-fltr-cnt {
    background-color: #21262d !important; border-color: #2d333b !important; }
  /* Tenant blue on the filter heading and "Always Active", plus a mid-grey Clear Filters
     label: 2.6-3.4:1 once the panel darks. */
  #onetrust-pc-sdk #ot-filter-list-header, #onetrust-pc-sdk .ot-always-active {
    color: #5fb0e6 !important; }
  #onetrust-pc-sdk #clear-filters-handler { color: #c4cdd6 !important; }

  /* ---- Catch-all: any element ESPN paints white/near-white inline ---- */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"] { background-color: #1c2128 !important; }
  /* Dark text ESPN hardcodes (#1d1e1f / #48494a) → light, on our dark surfaces */
  [style*="color: rgb(29, 30, 31)"], [style*="color:#1d1e1f"],
  [style*="color: rgb(72, 73, 74)"], [style*="color:#48494a"] { color: #c4cdd6 !important; }

  /* ---- ESPN hardcoded GREY SCALE (clr-gray-01..09), applied via CLASSES not inline: stat
     numbers, leader values, box-score metadata, glossary, copyright. Remap the WHOLE scale,
     dark end -> light. ---- */
  .clr-gray-01, .clr-gray-02 { color: #e6edf3 !important; } /* #151617 / darkest → primary text (numbers, names) */
  .clr-gray-03 { color: #c4cdd6 !important; }               /* #48494a → body */
  .clr-gray-04, .clr-gray-05 { color: #9aa4ae !important; } /* #6c6d6f → muted metadata (still ≥4.5 on cards) */
  /* .clr-negative (live minute, losses) and .clr-positive (wins) are a live/gain-loss signal
     the metadata greys flatten. */
  .clr-negative { color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }
  .clr-positive { color: #4ac76a !important; -webkit-text-fill-color: #4ac76a !important; }
  /* .clr-brand-ESPN is the same red. Single class, so it ties with the .Schedule__Time /
     .ScoreCell__Time greys above and wins only by order — keep it below them. */
  .clr-brand-ESPN { color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }
  /* .clr-link is ESPN's link-blue utility (#06c); it marks the footer's Manage Privacy
     Preferences trigger among blue siblings and outranks both the .ot-sdk-show-settings grey
     and the .AnchorLink white by order. */
  .clr-link { color: #5fb0e6 !important; }
  /* Module / section / panel titles ESPN colors with a dark grey (#2b2c2d) */
  .Stats__LeadersTitle, .Table__Title, .Card__Header__Title, .module-header,
  .headerCell__title, .pageHeader__title, .Wrapper__Header, .ContentList__Title,
  .Stats__Title, .StatBlock__Title, .TeamLeaders__Title, .clr-black, [class*="__Title"] {
    color: #e6edf3 !important; }
  /* Stat / leader / box-score containers that hardcode the same darks via class */
  .Athlete__Text--2xl-emph, .Athlete__Text--xl-emph, .Athlete__Text--lg-emph,
  .Athlete__PlayerName, .Athlete__Link, .Athlete h3, .Athlete h2,
  .StatBlock__Value, .StatBlockInner__Value, .Leaders__Item__Value,
  .TeamLeaders__Item, .player-leader-value, .fw-bold {
    color: #e6edf3 !important; }
  .Athlete__Text--md-emph, .Athlete__Stats, .Athlete__NameDetails,
  .StatBlock__Label, .Leaders__Item__Label, .glossary__title, .glossary__abbr {
    color: #c4cdd6 !important; }
  .Stats__footerText, .Stats__footerEmph, .Stats__TotalRow, .glossary__item,
  .LegalFooter__Copyright, .LegalFooter__Link, .ContentMetadata,
  .GameInfo__Meta, .Gamestrip__Time, .ScoreboardScoreCell__Note,
  /* box-score footnote ("+/- denotes…") hardcodes #6c6d6f → ~2.9:1 on the card */
  .TableDetails__Note { color: #9aa4ae !important; }
  /* Stat headers / sortable column links that color via class */
  .StatsTable__headerLink, .stats-cell, .Table__TH .AnchorLink,
  .Table__TH svg { color: #c4cdd6 !important; fill: #c4cdd6 !important; }
  /* Box-score line scores + column headings (1 2 3 4 T) → readable text */
  .ScoreboardScoreCell__Value, .ScoreboardScoreCell__Lines,
  .gameLineScore { color: #c4cdd6 !important; }
  .ScoreboardScoreCell__Heading { color: #9aa4ae !important; }
  /* Video duration pill: dark translucent over media, light text */
  .Media__Duration, .Media__Time {
    background-color: rgba(13,17,23,0.78) !important; color: #ffffff !important; }
  /* Scoreboard / game metadata hardcoding the same darks WITHOUT clr-gray-* */
  .ScoreboardScoreCell__Record, .LocationDetail__Item,
  .News__Item__Description, .News__Item__Timestamp,
  .GameInfo, .MatchInfo__Detail, .MatchInfo__Meta { color: #9aa4ae !important; }
  /* Game-info / match-info panels ESPN paints a light grey (#edeef0) */
  .MatchInfo, .GameInfo__Content, .Gamestrip, .competitors {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .MatchInfo__Link, .MatchInfo a { color: #5fb0e6 !important; }
  /* A <div>, not an <a>, so the link rule never reaches its hardcoded #0066cc. */
  .BackToTop, .BackToTop a { color: #5fb0e6 !important; }

  /* ---- "More Sports" mega-menu + per-sport flyouts: .submenu-wrapper / ul.split, plus the
     bare inner <ul>/<li> the panel is actually painted on — the wrapper is dark but its
     direct-child <ul> ships white. ---- */
  .submenu-wrapper, ul.split, ul.split.three, .split.three, .submenu, .sub-nav-menu,
  .Nav__Secondary__Submenu, .Nav__Submenu, .nav-submenu, .navbar-submenu,
  .submenu-wrapper ul, .submenu-wrapper li, .submenu-wrapper .sub {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .submenu-wrapper a, ul.split a, .submenu a, .Nav__Secondary__Submenu a,
  .submenu-wrapper a span { color: #e6edf3 !important; }
  .submenu-wrapper a:hover, ul.split a:hover, .submenu a:hover,
  .submenu-wrapper a:hover span { color: #9bd4ff !important; }
  /* A CSS-border triangle; recolour its bottom border (the fill). Painted by the ACTIVE PARENT
     <li> ::before, not by the panel wrapper. */
  .submenu-wrapper::before, .submenu-wrapper::after,
  .submenu-wrapper ul::before, .submenu-wrapper ul::after,
  .submenu-parent-active::before, .submenu-parent-active::after,
  #global-header li.user a::before, #global-header li.user a::after,
  #global-header li.search a::before, #global-header li.search a::after {
    border-bottom-color: #1c2128 !important; border-top-color: #1c2128 !important; }
  /* The SELECTED sport's caret is a different pseudo (li.active, no flyout) filled with the
     SECONDARY bar's colour, not the flyout's, so it must track the bar. Sport pages only. */
  #global-nav > ul > li.active::before,
  #global-nav > ul > li.submenu-parent-active::before {
    border-bottom-color: #0d1117 !important; }

  /* ---- Per-sport SECONDARY nav dropdowns: the panel is a bare unclassed <div> holding a
     ul.single / ul.split, which no .submenu-wrapper rule above reaches. ---- */
  #global-nav-secondary li.has-sub > div,
  #global-nav-secondary li.has-sub > div div,
  #global-nav-secondary li.has-sub > div ul,
  #global-nav-secondary li.has-sub > div li,
