  #global-nav ul > li.teams div:not(.link-text):not(.nav-logo-wrap),
  #global-nav ul > li.leagues-teams div:not(.link-text):not(.nav-logo-wrap),
  #global-nav-secondary ul li.teams div:not(.link-text):not(.nav-logo-wrap) {
