  /* --color-neutral-0 is shared with white text, so the Gamestrip header darks through its
     container instead. */
  .Gamestrip, .Gamestrip__Container, .Gamestrip__StickyContainer { background-color: #14181d !important; }
  .Gamestrip__Container > div { background-color: #14181d !important; }
  .Media__Caption, .Media__Caption--card { background-color: #1c2128 !important; }
  /* Next-gen light-theme cards hardcoding a white panel bg. Scope to the light-theme wrapper
     so feed cards elsewhere are untouched. ---- */
  .theme-light .contentItem__content, .theme-light .contentItem__contentWrapper,
  .theme-light .GameStory, .GameStory .contentItem__content { background-color: #1c2128 !important; }
  /* The track is light grey and the ACTIVE segment a hardcoded white pill (shared --color-
     neutral-0, not token-remappable). Hooked by role / data-testid. ---- */
  [data-testid="prism-tab-list"] [role="tablist"] {
    background-color: #14181d !important; border-color: #2d333b !important; }
  [data-testid="prism-tab-list"] [role="tab"],
  [data-testid="prism-ButtonBase"][role="tab"] { background-color: transparent !important; color: #9aa4ae !important; }
  [data-testid="prism-tab-list"] [role="tab"][aria-selected="true"],
  [data-testid="prism-ButtonBase"][role="tab"][aria-selected="true"] {
    background-color: #2d333b !important; color: #e6edf3 !important; }
  /* A white panel plus a white caret pseudo. */
  .ShotChart__Court__Play__Tooltip {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .ShotChart__Court__Play__Tooltip::before, .ShotChart__Court__Play__Tooltip::after {
    background-color: #1c2128 !important; border-color: #1c2128 !important; }
  /* MISSED is a hollow white disc with a team-colour ring, MADE a solid team-colour disc, both
     carrying the value inline, so the inline-white catch-all would darken missed — and an
     achromatic team's near-black would collapse the two. Keep missed white; the court is a
     light brand graphic we never darken. */
  .ShotChart__Court__Play:not(.ShotChart__Court__Play--made) {
    background-color: #ffffff !important; }
  /* Odds-cell values hardcode pure black (--color-neutral-1000). */
  [data-testid="OddsCell"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [data-testid="OddsCell"], [data-testid="OddsCell"] * {
    color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }
  /* The badge sits on a red/green chip but its label resolves through --color-combo-white-
     gray90, which we dark as a SURFACE elsewhere. */
  .ShotCard__GoalMouth, .ShotCard__GoalMouth * {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }

  /* ---- MLB gamecast live tracker: batter/pitcher header, pitch-zone surround, on-base strip
     and pitch-list rows ship a solid WHITE panel, hardcoded rather than token-driven. The
     coloured strike-zone cells and batter illustration are separate children. ---- */
  .Gamecast__Baseball, .Gamecast__Baseball .StatusBar__Slide,
  .Gamecast__Baseball .StatusBar__Module__BatterPitcher,
  .Gamecast__Baseball .StatusBar__Module__PlayerIntro,
  .OnBase__Wrapper, .PitchTracker__Pitch {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .Gamecast__Baseball .headshot { background-color: #1c2128 !important; }
  /* White-on-white natively; let the darked panel show through. */
  .FieldView__Square--hidden { background-color: transparent !important; }
  /* The EMPTY pitch-count orb is a solid WHITE fill while --filled is a coloured disc, so on
     dark an empty orb reads as LIT. Hollow slot with a muted ring; --filled keeps ESPN's
     colour as the signal. ---- */
  .PitchCount__Orb:not(.PitchCount__Orb--filled) {
    background-color: transparent !important; border-color: #4a525b !important; }
  /* ESPN fills a lit strike/out orb with `var(--bg-surface-raised, #d00)`: the token is unset
     natively so the red fallback paints, but the token block below defines it as the card
     surface, which makes a lit orb identical to the panel. Balls resolve through a token the
     block never defines, so only their ring needs restating past the `*` reset. */
  .PitchCount__Strikes .PitchCount__Orb--filled, .PitchCount__Outs .PitchCount__Orb--filled {
    background-color: #dd0000 !important; border-color: #dd0000 !important; }
  .PitchCount__Balls .PitchCount__Orb--filled { border-color: #009944 !important; }
  /* The SCOREBOARD's .BaseballSituation uses .pitches .circle, not .PitchCount__Orb, and fills
     a lit orb through a design token our block remaps to the card surface. The .green modifier
     needs three classes to clear the two-class red rule; the unlit ring is flattened by the
     `*` reset. */
  .pitches .circle.active {
    background-color: #dd0000 !important; border-color: #dd0000 !important; }
  .pitches .circle.active.green {
    background-color: #009944 !important; border-color: #009944 !important; }
  .pitches .circle:not(.active) { border-color: #4a525b !important; }
  /* A runner on base is encoded with .brdr-clr-link against the empty base's .brdr-clr-
     gray-06, both collapsed by the `*` border reset. The legacy .cscore diamonds carry neither
     utility (a border-bottom from a .base-<n>-<n>-<n> parent, !important), so only the SPA
     scoreboard breaks. */
  .diamond.brdr-clr-gray-06 { border-color: #4a525b !important; }
  .diamond.brdr-clr-link { border-color: #5fb0e6 !important; }
  /* the StatusBar carousel transition panes paint a full-size white ::before */
  .StatusBar__TransitionPane::before, .StatusBar__TransitionPane::after {
    background-color: #1c2128 !important; }
  /* win-probability legend team names + gamecast weather temp hardcode near-black. */
  .CustomLegend__TeamName { color: #e6edf3 !important; }
  /* The .CustomLegend container hands children a near-black; the percentage is a <div> and
     inherits it. */
  .CustomLegend__Team__Percent { color: #c4cdd6 !important; }
  /* The legend swatch carries its team colour twice inline: a top-to-transparent gradient and
     a 1px ring. The ring is an open set of team hexes no rule can restate, and the `*` reset
     greys it into a neutral box, so the ring goes and the gradient extends under it. */
  .CustomLegend__Rect {
    border-color: transparent !important; background-origin: border-box !important; }
  .Weather__Temp, .Weather__Items, .Weather__HiLow { color: #c4cdd6 !important; }
  /* Recharts ticks paint through a `fill` presentation attribute, out of reach of the token
     remaps and any `color` rule. Only the axis scale; series keep their team colours. */
  .recharts-cartesian-axis-tick text, .recharts-cartesian-axis-tick tspan,
  .recharts-cartesian-axis-tick-value { fill: #9aa4ae !important; }
  /* Light-grey ::after divider; the mobile score cell draws the same rule as
     .ScoreCell__Overview::before. */
  .ScoreCell__CompetitorDetails::after,
  .ScoreCell__Overview::before, .ScoreCell__Overview::after { background-color: #2d333b !important; }
  /* Split by a light-grey ::after vertical divider. ---- */
  .Athletes__Container .Athlete::after, .Athletes__Container .Athlete::before {
    background-color: #2d333b !important; }

  /* ---- More pseudo-element hairlines: the vertical rule in every scoreboard chip and the
     scores-carousel label underline. ---- */
  .cscore_overview::before, .cscore_overview::after,
  .scoreLabel_content::before, .scoreLabel_content::after {
    background-color: #2d333b !important; }
  /* Each one-feed leaderboard row separates its score and movement columns with a 1px ::after
     on the row anchor. ---- */
  .cscore_link::after { background-color: #2d333b !important; }

  /* ---- 404 page ships its own white hero panel and near-white quick-links block.
     .Error404__Footer is a <footer>, and the theme drops the bare `footer` selector. ---- */
  .Error404, .Error404__Wrapper, .Error404__QuickLinks, .Error404__Footer {
    background-color: #14181d !important; border-color: #2d333b !important; }
  .Error404__QuickLinks::before, .Error404__QuickLinks::after {
    background-color: #2d333b !important; }

  /* ---- A raster divider (greyline.png): a light bar image no background rule can touch. ---- */
  img[src*="greyline"] { filter: invert(1) !important; }
  /* The other embedded raster divider (_end_rule.png) is a solid PURE-BLACK bitmap with no
     alpha, so a plain invert would flip it to full white. ---- */
  img[src*="_end_rule"] { filter: invert(1) brightness(0.2) !important; }

  /* ---- Story Share flyout (.share-popup): a solid #fff card with dark ink, display:none
     until .popup-active. Its item anchors are `color: inherit !important` in ESPN's sheet, so
     setting the PANEL's colour is what repaints them — a rule on .share-popup-link loses the
     tie. The copy-link success state hardcodes a dark green. ---- */
  .share-button-wrapper .share-popup {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  .share-button-wrapper .share-popup .copy-link.active-copy-link .copy-link-inner {
    color: #4ac76a !important; -webkit-text-fill-color: #4ac76a !important; }
  /* These two take a light chip on hover and while their popup is open, and their glyphs are
     RASTER icons authored near-black. The invert is keyed to the two glyph files, not the
     shared .reactions-button class, because .reactions-count-button beside them carries
     coloured emoji. */
  .reactions-hover-button:hover,
  .share-button-wrapper.popup-active .reactions-hover-button {
    background-color: #2d333b !important; }
  .reactions-button img[src*="share-ios-on_light"],
  .reactions-button img[src*="heart-light-unfilled"] { filter: invert(1) !important; }

  /* ---- ESPN reds the LIVE .game-time and leaves the "0 Outs" span inside it neutral. Our
     live-red rule sets -webkit-text-fill-color, which INHERITS into that child, so it needs a
     direct declaration. ---- */
  .game-strip__outs {
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }

  /* ---- Each .HitMap cell is a saturated brand fill with a WHITE average in a bare unclassed
     <span> the generic span rule would grey. ---- */
  .HitMap__Item, .HitMap__Item span {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }

  /* ---- The ProgressBar TRACK is a hardcoded light grey; the team-coloured fill is a child
     div, so darking the track keeps brand colours. ---- */
  [data-testid="prism-ProgressBar"] { background-color: #3a4149 !important; }

  /* ---- Each legend swatch carries its TEAM colour via an inline --legend-color property,
     border-drawn, so the blanket * { border-color } greys it. ---- */
  .GraphHeader__ColorLegend { border-color: var(--legend-color) !important; }
  /* An achromatic team gets a near-black instead of a brand hue, so its curve and legend dash
     vanish on dark. Chromatic colours match neither selector. */
  stop[stop-color="#1d1e1f"] { stop-color: #c4cdd6 !important; }
  .GraphHeader__ColorLegend[style*="#1d1e1f"] { border-color: #c4cdd6 !important; }

  /* ---- ESPNIcons glyphs drawn through ::before / ::after in ESPN's hardcoded darks or link-
     blue: carousel arrows, sub-nav carets, external-link markers, the filter caret. ---- */
  #global-scoreboard .scores-prev::before, #global-scoreboard .scores-next::before,
  .scoreCenter .scores-prev::before, .scoreCenter .scores-next::before,
  #global-nav-secondary .global-nav-container > ul > li.has-sub > a::after,
  #global-nav-secondary .tertiary-nav li.has-sub > a::after,
  .button-filter::before, .button-filter::after,
  .quicklinks_list__icon::before, .contentItem__content__meta::after,
  a.external::after, li.external > a::after { color: #9aa4ae !important; }

  /* ---- Quick-links / network-logo slots carry RASTER brand marks; ESPN serves the near-black
     variant of several (`_bk`, `-black`). The slot holds nothing but the <img>, so a filter is
     safe, but it MUST be keyed per file: the same slots hold full-colour marks an invert would
     wreck. The bare hash is the X Games category id, the only hook on artwork.espncdn.com.
     ---- */
  .quicklinks_list__icon img[src*="black.png"],
  .quicklinks_list__icon img[src*="instagram.png"],
  .quicklinks_list__icon img[src*="bf9d0869"],
  .quicklinks_list__icon img[src*="_bk.png"],
  .contentItem__logo img[src*="black.png"],
  .contentItem__logo img[src*="_bk.png"] { filter: invert(1) !important; }

  /* ---- Card top rule: .contentItem__teamBorder and its Prism successor .ColorBorder carry
     the TEAM colour inline; a card with no team gets a light neutral instead. No CSS can test
     a colour for chroma, so the neutral fallbacks are enumerated on two axes: ESPN swaps WHICH
     grey it uses (#cbccce, #FFFFFF, #a5a6a7), and a client-side re-render comes back as
     `rgb(165, 166, 167)` because the CSSOM re-serialises the attribute. Hence hex in both
     cases and rgb in both spacings, on both classes. Chromatic team colours match none of
     these. ---- */
  .ColorBorder[style*="#848687"], .contentItem__teamBorder[style*="#848687"],
  .ColorBorder[style*="rgb(132, 134, 135)"], .contentItem__teamBorder[style*="rgb(132, 134, 135)"],
  .ColorBorder[style*="rgb(132,134,135)"], .contentItem__teamBorder[style*="rgb(132,134,135)"],
  .ColorBorder[style*="#a5a6a7"], .contentItem__teamBorder[style*="#a5a6a7"],
  .ColorBorder[style*="#A5A6A7"], .contentItem__teamBorder[style*="#A5A6A7"],
  .ColorBorder[style*="rgb(165, 166, 167)"], .contentItem__teamBorder[style*="rgb(165, 166, 167)"],
  .ColorBorder[style*="rgb(165,166,167)"], .contentItem__teamBorder[style*="rgb(165,166,167)"],
  .ColorBorder[style*="#b5b7b7"], .contentItem__teamBorder[style*="#b5b7b7"],
  .ColorBorder[style*="#B5B7B7"], .contentItem__teamBorder[style*="#B5B7B7"],
  .ColorBorder[style*="rgb(181, 183, 183)"], .contentItem__teamBorder[style*="rgb(181, 183, 183)"],
  .ColorBorder[style*="rgb(181,183,183)"], .contentItem__teamBorder[style*="rgb(181,183,183)"],
  .ColorBorder[style*="#cbccce"], .contentItem__teamBorder[style*="#cbccce"],
  .ColorBorder[style*="#CBCCCE"], .contentItem__teamBorder[style*="#CBCCCE"],
  .ColorBorder[style*="rgb(203, 204, 206)"], .contentItem__teamBorder[style*="rgb(203, 204, 206)"],
  .ColorBorder[style*="rgb(203,204,206)"], .contentItem__teamBorder[style*="rgb(203,204,206)"],
  .ColorBorder[style*="#cfd0d1"], .contentItem__teamBorder[style*="#cfd0d1"],
  .ColorBorder[style*="#CFD0D1"], .contentItem__teamBorder[style*="#CFD0D1"],
  .ColorBorder[style*="rgb(207, 208, 209)"], .contentItem__teamBorder[style*="rgb(207, 208, 209)"],
  .ColorBorder[style*="rgb(207,208,209)"], .contentItem__teamBorder[style*="rgb(207,208,209)"],
  .ColorBorder[style*="#d9d9d9"], .contentItem__teamBorder[style*="#d9d9d9"],
  .ColorBorder[style*="#D9D9D9"], .contentItem__teamBorder[style*="#D9D9D9"],
  .ColorBorder[style*="rgb(217, 217, 217)"], .contentItem__teamBorder[style*="rgb(217, 217, 217)"],
  .ColorBorder[style*="rgb(217,217,217)"], .contentItem__teamBorder[style*="rgb(217,217,217)"],
  .ColorBorder[style*="#dcdddf"], .contentItem__teamBorder[style*="#dcdddf"],
  .ColorBorder[style*="#DCDDDF"], .contentItem__teamBorder[style*="#DCDDDF"],
  .ColorBorder[style*="rgb(220, 221, 223)"], .contentItem__teamBorder[style*="rgb(220, 221, 223)"],
  .ColorBorder[style*="rgb(220,221,223)"], .contentItem__teamBorder[style*="rgb(220,221,223)"],
  .ColorBorder[style*="#e4e5e6"], .contentItem__teamBorder[style*="#e4e5e6"],
  .ColorBorder[style*="#E4E5E6"], .contentItem__teamBorder[style*="#E4E5E6"],
  .ColorBorder[style*="rgb(228, 229, 230)"], .contentItem__teamBorder[style*="rgb(228, 229, 230)"],
  .ColorBorder[style*="rgb(228,229,230)"], .contentItem__teamBorder[style*="rgb(228,229,230)"],
  .ColorBorder[style*="#edeef0"], .contentItem__teamBorder[style*="#edeef0"],
  .ColorBorder[style*="#EDEEF0"], .contentItem__teamBorder[style*="#EDEEF0"],
  .ColorBorder[style*="rgb(237, 238, 240)"], .contentItem__teamBorder[style*="rgb(237, 238, 240)"],
  .ColorBorder[style*="rgb(237,238,240)"], .contentItem__teamBorder[style*="rgb(237,238,240)"],
  .ColorBorder[style*="#f1f2f3"], .contentItem__teamBorder[style*="#f1f2f3"],
  .ColorBorder[style*="#F1F2F3"], .contentItem__teamBorder[style*="#F1F2F3"],
  .ColorBorder[style*="rgb(241, 242, 243)"], .contentItem__teamBorder[style*="rgb(241, 242, 243)"],
  .ColorBorder[style*="rgb(241,242,243)"], .contentItem__teamBorder[style*="rgb(241,242,243)"],
  .ColorBorder[style*="#f5f5f5"], .contentItem__teamBorder[style*="#f5f5f5"],
  .ColorBorder[style*="#F5F5F5"], .contentItem__teamBorder[style*="#F5F5F5"],
  .ColorBorder[style*="rgb(245, 245, 245)"], .contentItem__teamBorder[style*="rgb(245, 245, 245)"],
  .ColorBorder[style*="rgb(245,245,245)"], .contentItem__teamBorder[style*="rgb(245,245,245)"],
  .ColorBorder[style*="#ffffff"], .contentItem__teamBorder[style*="#ffffff"],
  .ColorBorder[style*="#FFFFFF"], .contentItem__teamBorder[style*="#FFFFFF"],
  .ColorBorder[style*="rgb(255, 255, 255)"], .contentItem__teamBorder[style*="rgb(255, 255, 255)"],
  .ColorBorder[style*="rgb(255,255,255)"], .contentItem__teamBorder[style*="rgb(255,255,255)"] {
    background-color: #2d333b !important; }

  /* ---- Percentages and their "%" suffix hardcode near-black; the team abbreviations are
     already light. */
  .matchupPredictor__teamValue, .matchupPredictor__teamValue div,
  .matchupPredictor__suffix { color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }

  /* ---- Headshot discs are a solid white circle behind a transparent PNG. .headshot-md is the
     one-feed shortstop variant and .author-img the byline mugshot — same disc, different
     class. */
  .headshot, .headshot-md, .author-img { background-color: #1c2128 !important; }
  /* The disc outline is an inset box-shadow, not a border. */
  .headshot, .headshot-sm, .headshot-md, .author-img {
    box-shadow: 0 0 0 1px #2d333b inset !important; }

  /* With no image, ESPN paints a light rounded box holding a faint ESPN wordmark. */
  .News__Item__Thumbnail.no-img, .News__Item__Thumbnail--no-img,
  .Thumbnail.no-img { background-color: #1c2128 !important; }

  /* ---- espnfitt maps its .bg-clr-gray-NN SURFACE utilities onto the same --color-neutral-*
     tokens we remap for TEXT, so gray-01/02 would resolve to our light text greys. Pin the
     surface utilities so they no longer ride the text tokens. ---- */
  .bg-clr-gray-01, .bg-clr-gray-02 { background-color: #0d1117 !important; }
  .bg-clr-gray-03, .bg-clr-gray-04, .bg-clr-gray-05 { background-color: #21262d !important; }
  .bg-clr-gray-06, .bg-clr-gray-07, .bg-clr-gray-08,
  .bg-clr-gray-09, .bg-clr-gray-10 { background-color: #1c2128 !important; }
  /* The dark icon rail is ul.tier-1 (riding the bg-clr-gray utilities above), but the sport-
     list ul.tier-2 and nested ul.tier-3 ship a solid WHITE panel. ---- */
  #global-nav-mobile ul.tier-2, #global-nav-mobile ul.tier-3,
  #global-nav-mobile ul.tier-2 li, #global-nav-mobile ul.tier-3 li {
    background-color: #14181d !important; border-color: #262c33 !important; }
  #global-nav-mobile ul.tier-2 a:hover, #global-nav-mobile ul.tier-3 a:hover {
    background-color: #1c2128 !important; }
  /* The mobile-nav search reveal expands to a near-white panel. Scope to the mobile nav so the
     transparent desktop .global-search is untouched. ---- */
  #global-nav-mobile .global-search { background-color: #14181d !important; }
  /* A solid white 50x50 box with a dark calendar glyph, espnfitt-only. ---- */
  .DateCarousel__MonthTrigger {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .DateCarousel__MonthTrigger svg, .DateCarousel__MonthTrigger path,
  .DateCarousel__MonthTrigger use { fill: #c4cdd6 !important; }
  /* The popover it opens is a solid-white card with a near-white halo box-shadow. Its month
     caption is a hardcoded near-black that survives our token remaps, and ESPN separates the
     SELECTED day by tone, which our broad text rule would flatten. */
  .DatePicker__MonthContainer, .DatePicker__MonthContainer.calendar--embedded {
    background-color: #1c2128 !important; border-color: #2d333b !important;
    box-shadow: 0 0 3px 3px #14181d !important; }
  .MonthContainer__MonthYear { color: #e6edf3 !important; }
  .MonthContainer__Day--selected {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }
  /* Today / Cancel are <div>s, not anchors, so the link rule never reaches their #0066cc. */
  .MonthContainer__button { color: #5fb0e6 !important; }
  /* Two pseudo-elements the `*` reset cannot reach: ::before the CSS-triangle pointer, ::after
     the rotated rule under the caption. The trigger's ::before is the same story. */
  .MonthContainer__Header::before { border-bottom-color: #1c2128 !important; }
  .MonthContainer__Header::after { border-color: #2d333b !important; }
  .DateCarousel__MonthTrigger::before {
    background-color: #2d333b !important; border-color: #2d333b !important; }
  /* A solid WHITE nav band below the header. Mobile-frontend-only. Its transparent-PNG logos
     and blue icon-font glyphs survive on dark. ---- */
  ul.fav-menu.strip, .fav-menu.strip.mobile { background-color: #14181d !important; }
  ul.fav-menu.strip li:hover, .fav-menu.strip.mobile li:hover { background-color: #1c2128 !important; }
  /* .oddsStripWrapper hardcodes #fff, .oddsStrip a light grey, and the accordion caret is a
     pure-black ESPNIcons pseudo. The betting rows are natively transparent, so the theme's
     [class*="betting"] surface rule must be cleared in this scope. ---- */
  .oddsStripContent .oddsStripWrapper { background-color: #1c2128 !important; }
  .oddsStripContent .oddsStrip { background-color: #21262d !important; }
  .oddsStrip .bettingWrapper, .oddsStrip .betting, .oddsStrip .bettingLabel,
  .oddsStrip .bettingPrimary, .oddsStrip .bettingSecondary,
  .oddsStrip .bettingTeamSeparator { background-color: transparent !important; }
  .oddsStripCaret, .oddsStripCaret::before { color: #c4cdd6 !important; }

  /* ---- Taboola "why this ad" fade / popover panels are solid white. ---- */
  .trc_exclude_overlay, .trc_popover, .trc_popover_title_wrapper {
    background-color: #1c2128 !important; }

  /* ---- Carousel arrows: the legacy slick arrows and the prism .CarouselArrow each ship a
     translucent WHITE disc. The slick glyph is an ESPNIcons char painted link-blue; the
     CarouselArrow glyph is already white. ---- */
  .slick-prev, .slick-next, .CarouselArrow, button.CarouselArrow {
    background-color: rgba(20,24,29,0.7) !important; }
  .slick-prev::before, .slick-next::before { color: #e6edf3 !important; }
  /* Both draw a brand-blue ring (1px slick, 2px .CarouselArrow) that the blanket `*` reset
     greys into the thumbnail. */
  .slick-prev, .slick-next, .CarouselArrow, button.CarouselArrow {
    border-color: #4c99e6 !important; }

  /* ---- ESPN paints .MediaList__item__playing native red. .mediaList__phase is the legacy
     equivalent — a span inside an anchor, so the `a span` blue rule flattens that one instead.
     ---- */
  .MediaList__item__playing, .mediaList__phase {
    color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }

  /* ---- ESPN authors this `fill: var(--icon-default, var(--color-red-600, #d00))`, so it is
     red only because --icon-default is undefined on the light site; our fusion block defines
     that token. ---- */
  .SoccerPerformers__RedCardIcon { fill: #ff5a5a !important; }

  /* ---- The first team's segment carries its fill INLINE, the second is a diagonal hatch. Two
     inline values land at ~1.0:1 on dark: ESPN's neutral #1d1e1f and pure #000000 for a black-
     kitted club. Both nodes carry only hashed classes, so the inline value is the only hook;
     the swatch is a <span>, the bar the testid. ---- */
  [data-test-id="prism-progress-bar"][style*="rgb(29, 30, 31)"],
  [data-test-id="prism-progress-bar"][style*="#1d1e1f"],
  [data-test-id="prism-progress-bar"][style*="rgb(0, 0, 0)"],
  [data-test-id="prism-progress-bar"][style*="#000000"],
  span[style*="background:#1d1e1f"],
  span[style*="background:#000000"] { background-color: #c4cdd6 !important; }

  /* ---- ESPN paints each W/L/D badge its outcome colour as a form signal; the badge is a span
     inside an .AnchorLink, so the a / a span blue rule flattens all three. The span carries
     BOTH .GameResults and its --win/--loss modifier, so a two-class selector clears the tie.
     ---- */
  span.GameResults { color: #9aa4ae !important; -webkit-text-fill-color: #9aa4ae !important; }
  .GameResults.GameResults--win {
    color: #4ac76a !important; -webkit-text-fill-color: #4ac76a !important; }
  .GameResults.GameResults--loss {
    color: #ff5a5a !important; -webkit-text-fill-color: #ff5a5a !important; }

  /* ---- ESPN Radio player. The video.js `.audio` skin is the inverse of the video one: solid
     #fff stage, caption layer, now-playing block and settings menu with black ink and black
     icon-font glyphs, plus .RadioContact__Content #fff inside a dark .Card. Only `.audio` is
     named — the video skin is already black and must stay so. Control glyphs are each button's
     own ::before inheriting `color`; the scrubber and volume fills are real backgrounds and
     invert separately. ---- */
  .evp-player.audio, .evp-player.audio .vjs-text-track-display,
  .evp-player.audio .vjs-menu, .audio-content-container, .RadioContact__Content {
    background-color: #1c2128 !important; }
  /* The contact card's handle is a leaf .AnchorLink in link blue. */
  .RadioContact .AnchorLink { color: #5fb0e6 !important; }
  .evp-player.audio, .evp-player.audio .vjs-control, .evp-player.audio button,
  .audio-content-container { color: #c4cdd6 !important; }
  /* .vjs-progress-holder also carries .vjs-slider but is the 30px HIT AREA, not the 4px track
     — painting the shared class turns the scrubber into a thick slab. */
  .evp-player.audio .vjs-volume-bar,
  .evp-player.audio .evp-progress-holder-wrapper { background-color: #3a4149 !important; }
  .evp-player.audio .vjs-load-progress { background-color: #4a525b !important; }
  .evp-player.audio .vjs-play-progress, .evp-player.audio .vjs-volume-level {
    background-color: #c4cdd6 !important; }
  /* Every transport glyph is a data-URI SVG background-image with a hardcoded black fill on a
     transparent ::before, so inverting the pseudo flips the glyph alone. The LIVE chip draws
     both its box and its label in one such SVG on the button itself, so clearing the
     background-image would delete the word LIVE. */
  .evp-player.audio .vjs-control::before,
  .evp-player.audio .vjs-menu-button::before,
  .evp-player.audio .vjs-icon-placeholder::before { filter: invert(1) !important; }
  .evp-player.audio .vjs-seek-to-live-control { filter: invert(1) !important; }
  /* The one glyph ESPN ships already WHITE, invisible by design on the white stage; sink it to
     the panel tone. */
  .evp-player.audio .vjs-big-play-button::before {
    filter: invert(1) brightness(0.16) !important; }
  /* The Autoplay switch draws its whole track as a 1px #0066cc ring on .toggle-checkbox and
     only swaps the ::after knob, so the blanket `*` reset erases the track. */
  .toggle-checkbox { border-color: #5fb0e6 !important; }
  /* The Share control opens a 290px #fff card (`.vjs-share-open .vjs-branded-social-overlay`)
     whose title and links are near-black natively; the theme's h3 white and link blue land on
     that white card, so the panel needs the dark tone the rest of the skin takes. */
  .evp-player.audio.vjs-share-open .vjs-branded-social-overlay {
    background-color: #1c2128 !important; }

  /* ---- fantasy.espn.com marketing pages (a claimed espn.com subdomain on its own Next.js
     frontend): secondary nav, feature bands and support module ship solid #fff, plus a near-
     white linear-gradient on the app-upsell band that no background-COLOR rule reaches. The
     jsx-<hash> class beside each rotates every deploy; the semantic class is the stable hook.
     ---- */
  nav.NavSecondary, .CompeteWithFriends, .SupportModule, .chat--container--wrapper {
    background-color: #1c2128 !important; }
  .WelcomeMobileUpsell {
    background-color: #14181d !important; background-image: none !important; }
  /* Its dividers are pseudo bars and a border-TOP longhand on the upsell card — one class with
     !important, so the blanket `*` reset, which only sets the shorthand at (0,0,0), loses. */
  .NavSecondary__Link::after, .GridironGauntletGameplay__Content::after {
    background-color: #2d333b !important; }
  .Card__Content { border-top-color: #2d333b !important; }
  /* A grey picked for the white page, outside the .clr-gray-* scale the theme remaps. */
  .LargeRadioControl__Description { color: #9aa4ae !important; }
  /* Also outside the .clr-gray-* scale. */
  .SelectableCard__Description { color: #9aa4ae !important; }
  /* An unclassed <h2> painted fantasy lime on the page's own blue artwork, which the theme
     never darkens. */
  .league-onboarding-header-wrapper h2 {
    color: #cfff18 !important; -webkit-text-fill-color: #cfff18 !important; }
}
